    private Panel?        _sidebar;
    private Panel?        _content;
    private readonly Dictionary<string, Button> _navButtons = new();

    private void InitializeComponent()
    {
        SuspendLayout();

        // ---------------- Form ----------------
        Text          = "Whitehat Security Dashboard";
        Size          = new Size(1080, 720);
        StartPosition = FormStartPosition.CenterScreen;
        BackColor     = Theme.Bg;
        ForeColor     = Theme.TextMain;
        Font          = Theme.Body();
        MinimumSize   = new Size(960, 600);

        // ---------------- Sidebar ----------------
        _sidebar = new Panel
        {
            Dock      = DockStyle.Left,
            Width     = 200,
            BackColor = Theme.Sidebar,
            Padding   = new Padding(0, 12, 0, 12),
        };
        Controls.Add(_sidebar);

        var logo = new Label
        {
            Text      = "Whitehat Security",
            ForeColor = Theme.Accent,
            Font      = new Font("Segoe UI", 13, FontStyle.Bold),
            AutoSize  = false,
            TextAlign = ContentAlignment.MiddleCenter,
            Dock      = DockStyle.Top,
            Height    = 36,
        };
        var version = new Label
        {
            Text      = $"v{Installer.ProductVersion} Dashboard",
            ForeColor = Theme.TextDim,
            Font      = new Font("Segoe UI", 8),
            AutoSize  = false,
            TextAlign = ContentAlignment.MiddleCenter,
            Dock      = DockStyle.Top,
            Height    = 20,
        };
        _sidebar.Controls.Add(version);
        _sidebar.Controls.Add(logo);

        // Add a small spacer between header and nav buttons
        _sidebar.Controls.Add(new Panel { Dock = DockStyle.Top, Height = 16, BackColor = Theme.Sidebar });

        // ---------------- Content host ----------------
        _content = new Panel
        {
            Dock      = DockStyle.Fill,
            BackColor = Theme.Bg,
            Padding   = new Padding(20),
        };
        Controls.Add(_content);
        _content.BringToFront();

        // ---------------- Pages (built before nav buttons so we can wire them) ----------------
        _navPages["Status"]    = BuildStatusPage();
        _navPages["Alerts"]    = BuildAlertsPage();
        _navPages["AI"]        = BuildAiThreatsPage();
        _navPages["Settings"]  = BuildSettingsPage();
        _navPages["Logs"]      = BuildLogsPage();
        _navPages["Console"]   = BuildConsolePage();

        foreach (var page in _navPages.Values)
        {
            page.Dock     = DockStyle.Fill;
            page.Visible  = false;
            _content.Controls.Add(page);
        }

        // ---------------- Sidebar nav buttons ----------------
        // Buttons are added top-to-bottom; we add in reverse order so the
        // top-of-list ends up at the top of the Dock=Top stack.
        AddNavButton("Console", "[>]  Console");
        AddNavButton("Logs",    "[L]  Logs");
        AddNavButton("Settings","[C]  Settings");
        AddNavButton("AI",      "[B] Behaviour Scan");
        AddNavButton("Alerts",  "[A]  Alerts");
        AddNavButton("Status",  "[S]  Status");

        // Default page
        ShowPage("Status");

        ResumeLayout(false);
    }

    private void AddNavButton(string key, string label)
    {
        var btn = new Button
        {
            Text       = label,
            Dock       = DockStyle.Top,
            Height     = 40,
            FlatStyle  = FlatStyle.Flat,
            BackColor  = Theme.Sidebar,
            ForeColor  = Theme.TextMain,
            Font       = Theme.NavBtn(),
            TextAlign  = ContentAlignment.MiddleLeft,
            Padding    = new Padding(16, 0, 0, 0),
            Cursor     = Cursors.Hand,
            Tag        = key,
            TabIndex   = key switch
            {
                "Status" => 0,
                "Alerts" => 1,
                "AI" => 2,
                "Settings" => 3,
                "Logs" => 4,
                _ => 5,
            },
        };
        btn.FlatAppearance.BorderSize        = 0;
        btn.FlatAppearance.MouseOverBackColor = Theme.BtnHover;
        btn.Click += (_, _) => ShowPage(key);
        _sidebar!.Controls.Add(btn);
        _navButtons[key] = btn;
    }

    private void ShowPage(string key)
    {
        if (key == "Logs" && _content is not null
            && _navPages.TryGetValue("Logs", out var previous))
        {
            _content.Controls.Remove(previous);
            previous.Dispose();
            var refreshed = BuildLogsPage();
            refreshed.Dock = DockStyle.Fill;
            _navPages["Logs"] = refreshed;
            _content.Controls.Add(refreshed);
        }

        foreach (var (k, page) in _navPages)
            page.Visible = (k == key);

        // Highlight the active nav button
        foreach (var (k, btn) in _navButtons)
            btn.BackColor = (k == key) ? Theme.BtnHover : Theme.Sidebar;
        if (_navButtons.TryGetValue(key, out var activeButton)
            && activeButton.CanSelect)
            activeButton.Select();
    }

    /// <summary>
    /// Public entry point used by TrayApplicationContext to switch tabs from
    /// the system-tray context menu.
    /// </summary>
    public void OpenTab(string key)
    {
        if (_navPages.ContainsKey(key)) ShowPage(key);
    }

