    private Panel BuildStatusPage()
    {
        var page = new Panel { BackColor = Theme.Bg, AutoScroll = true };

        var title = new Label
        {
            Text      = "Live Monitoring Status",
            Font      = Theme.PageTitle(),
            ForeColor = Theme.Accent,
            AutoSize  = true,
            Location  = new Point(8, 8),
        };
        page.Controls.Add(title);

        // Stat cards — keep references to the value labels so RefreshStatusPage
        // can update them on every tick.
        var (alertCard, alertVal) = BuildStatCard("TOTAL ALERTS", "0",     Theme.Red,    new Point(8,   60));
        var (connCard,  connVal)  = BuildStatCard("CONNECTIONS",  "0",     Theme.Accent, new Point(220, 60));
        var (procCard,  procVal)  = BuildStatCard("PROCESSES",    "0",     Theme.Green,  new Point(432, 60));
        var (upCard,    upVal)    = BuildStatCard("UPTIME",       "00:00", Theme.Orange, new Point(644, 60));
        page.Controls.AddRange(new Control[] { alertCard, connCard, procCard, upCard });
        _alertCountValue = alertVal;
        _connCountValue  = connVal;
        _procCountValue  = procVal;
        _uptimeValue     = upVal;

        // Computer info card
        var info = new Panel
        {
            Location  = new Point(8, 165),
            Size      = new Size(848, 70),
            BackColor = Theme.Card,
        };
        var infoLine = new Label
        {
            Text =
                $"Computer: {Environment.MachineName}    " +
                $"User: {Environment.UserName}    " +
                // Use the program start time captured in Program.cs (not
                // DateTime.Now at form-construction time, which would lie
                // by the difference between launch and dashboard open).
                $"Started: {Program.StartedAt:HH:mm:ss}    " +
                $"Architecture: {(Environment.Is64BitProcess ? "x64" : "x86")}",
            Font      = Theme.Mono(9, FontStyle.Bold),
            ForeColor = Theme.TextMain,
            AutoSize  = false,
            AutoEllipsis = true,
            Size      = new Size(816, 22),
            Location  = new Point(16, 24),
        };
        info.Controls.Add(infoLine);
        page.Controls.Add(info);

        // Security posture row
        var postureTitle = new Label
        {
            Text      = "Security Posture",
            Font      = new Font("Segoe UI", 10, FontStyle.Bold),
            ForeColor = Theme.Accent,
            AutoSize  = true,
            Location  = new Point(8, 250),
        };
        page.Controls.Add(postureTitle);

        var postureCard = new Panel
        {
            Location  = new Point(8, 275),
            Size      = new Size(848, 80),
            BackColor = Theme.Card,
        };
        // Posture row keys are indexed in this order. RefreshPostureIndicators
        // (in DashboardForm.cs) walks them and queries SecurityPosture for the
        // live state on every status timer tick.
        var postureKeys = new[]
        {
            "Defender", "Firewall", "UAC", "RDP",
            "SecureBoot", "TPM", "HVCI", "BitLocker",
        };
        for (int i = 0; i < postureKeys.Length; i++)
        {
            int col = i % 4;
            int row = i / 4;
            var lbl = new Label
            {
                Text      = "● " + postureKeys[i] + ": Unknown",
                AccessibleName = postureKeys[i] + ": Unknown",
                ForeColor = Theme.PostureNa,    // starts gray; refresh sets the real color
                Font      = new Font("Segoe UI", 9, FontStyle.Bold),
                AutoSize  = true,
                Location  = new Point(20 + col * 200, 18 + row * 28),
            };
            postureCard.Controls.Add(lbl);
            _postureLabels[postureKeys[i]] = lbl;
        }
        page.Controls.Add(postureCard);

        // Recent alerts list
        var recentTitle = new Label
        {
            Text      = "Recent Alerts",
            Font      = new Font("Segoe UI", 10, FontStyle.Bold),
            ForeColor = Theme.Accent,
            AutoSize  = true,
            Location  = new Point(8, 370),
        };
        page.Controls.Add(recentTitle);

        _recentList.Location      = new Point(8, 395);
        _recentList.Size          = new Size(848, 250);
        _recentList.View          = View.Details;
        _recentList.FullRowSelect = true;
        _recentList.GridLines     = false;
        _recentList.BackColor     = Theme.Card;
        _recentList.ForeColor     = Theme.BodyText;
        _recentList.Font          = Theme.Mono(9);
        _recentList.HeaderStyle   = ColumnHeaderStyle.Nonclickable;
        _recentList.Columns.Add("Time",     90);
        _recentList.Columns.Add("Severity", 70);
        _recentList.Columns.Add("Category", 110);
        _recentList.Columns.Add("Title",    540);
        page.Controls.Add(_recentList);

        void LayoutStatusPage()
        {
            var width = Math.Max(620, page.ClientSize.Width - 20);
            const int gap = 12;
            var cardWidth = Math.Max(130, (width - gap * 3) / 4);
            var cards = new[] { alertCard, connCard, procCard, upCard };
            for (var i = 0; i < cards.Length; i++)
            {
                cards[i].Left = 8 + i * (cardWidth + gap);
                cards[i].Width = cardWidth;
            }
            info.Width = width;
            infoLine.Width = Math.Max(120, info.ClientSize.Width - 32);
            postureCard.Width = width;
            var labels = postureCard.Controls.OfType<Label>().ToArray();
            var columnWidth = Math.Max(
                130, (postureCard.ClientSize.Width - 40) / 4);
            for (var i = 0; i < labels.Length; i++)
                labels[i].Left = 20 + (i % 4) * columnWidth;
            _recentList.Width = width;
            _recentList.Columns[3].Width = Math.Max(
                160, _recentList.ClientSize.Width - 285);
            page.AutoScrollMinSize = new Size(0, 660);
        }
        page.Resize += (_, _) => LayoutStatusPage();
        page.HandleCreated += (_, _) => LayoutStatusPage();

        return page;
    }

    /// <summary>
    /// Builds one of the four big stat cards on the Status page. Returns the
    /// card panel and the inner Label that holds the metric so the
    /// code-behind can update it on every tick.
    /// </summary>
    private (Panel card, Label valueLabel) BuildStatCard(
        string headerText, string initialValue, Color accent, Point location)
    {
        var card = new Panel
        {
            Size      = new Size(200, 90),
            BackColor = Theme.Card,
            Location  = location,
        };
        var bar = new Panel
        {
            Dock      = DockStyle.Left,
            Width     = 4,
            BackColor = accent,
        };
        card.Controls.Add(bar);

        var header = new Label
        {
            Text      = headerText,
            Font      = Theme.CardLabel(),
            ForeColor = Theme.TextDim,
            AutoSize  = true,
            Location  = new Point(16, 14),
        };
        var value = new Label
        {
            Text      = initialValue,
            Font      = Theme.CardValue(),
            ForeColor = Theme.TextMain,
            AutoSize  = true,
            Location  = new Point(16, 32),
        };
        card.Controls.Add(header);
        card.Controls.Add(value);

        return (card, value);
    }

