    // ============================================================================
    //  PAGE 4: SETTINGS  (27 toggles)
    // ============================================================================
    private Panel BuildSettingsPage()
    {
        var page = new Panel
        {
            BackColor  = Theme.Bg,
            AutoScroll = true,
        };

        int y = 8;

        // -------- Header --------
        var title = new Label
        {
            Text      = "Settings",
            Font      = Theme.PageTitle(),
            ForeColor = Theme.Accent,
            AutoSize  = true,
            Location  = new Point(8, y),
        };
        page.Controls.Add(title);
        y += 36;

        var subtitle = new Label
        {
            Text      = "Toggle which findings raise notifications. Changes save automatically. Items marked [admin] trigger UAC.",
            Font      = Theme.Body(9),
            ForeColor = Theme.TextDim,
            AutoSize  = false,
            Size      = new Size(600, 36),
            Location  = new Point(8, y),
        };
        page.Controls.Add(subtitle);
        FitToParent(subtitle, rightMargin: 24);
        // The label is 36 tall; advancing by 28 put the button row 8px on
        // top of it, so the last line of the description was struck through
        // by three buttons.
        y += 40;

        // -------- Reset / Export / Import button row --------
        var btnReset  = new Button { Text = "Reset App Defaults", Location = new Point(20,  y), Size = new Size(140, 28) };
        var btnExport = new Button { Text = "Export Config",     Location = new Point(166, y), Size = new Size(120, 28) };
        var btnImport = new Button { Text = "Import Config",     Location = new Point(292, y), Size = new Size(120, 28) };
        foreach (var b in new[] { btnReset, btnExport, btnImport })
        {
            b.FlatStyle = FlatStyle.Flat;
            b.BackColor = Theme.BtnHover;
            b.ForeColor = Theme.TextMain;
            b.Font      = new Font("Segoe UI", 9, FontStyle.Bold);
            b.Cursor    = Cursors.Hand;
            b.FlatAppearance.BorderSize = 0;
            page.Controls.Add(b);
        }
        btnReset.Click  += OnResetSettingsClick;
        btnExport.Click += OnExportSettingsClick;
        btnImport.Click += OnImportSettingsClick;
        y += 38;

        // -------- Notification Categories section --------
        y = AddSectionHeader(page, "Notification Categories", y);
        var categories = new (string Key, string Label, string Desc)[]
        {
            ("Firmware",   "Firmware Integrity Changes",   "Driver/firmware file hash modifications, deletions, new files"),
            ("Driver",     "Driver Changes",               "New drivers loaded or existing drivers removed"),
            ("Service",    "New Services",                 "Newly installed or registered Windows services"),
            ("Connection", "Unknown Network Connections",  "Outbound connections from unrecognized processes (off by default — noisy)"),
            ("Process",    "Unsigned Processes",           "New processes running without a valid digital signature"),
            ("Listener",   "New Listening Ports",          "New ports opened for incoming connections"),
            ("Registry",   "Registry Startup Key Changes", "Modifications to Run/RunOnce and tamper-protection keys"),
            ("Security",   SecurityEventsLabel(),          SecurityEventsDescription()),
            ("RDP",        "Remote Desktop (RDP) Status",  "Alert when Remote Desktop is enabled"),
            ("Hosts",      "Hosts File Modifications",     "Changes to the hosts file that could redirect DNS"),
        };
        foreach (var c in categories)
            y = AddSettingCheckbox(page, c.Key, c.Label, c.Desc, _config.IsCategoryEnabled(c.Key), y);

        // The behavioural engines raise their own categories. Before v7.4.8
        // they were absent from this page, so their alerts could not be
        // turned off at all.
        y = AddSectionHeader(page, "Behavioural Detection", y + 8);
        var behavioural = new (string Key, string Label, string Desc)[]
        {
            ("HiddenProcess", "Hidden Processes",       "Processes present in the kernel list but hidden from the normal API"),
            ("Memory",        "Executable Private Memory", "Read-write-execute private memory — the fingerprint of injected code"),
            ("BYOVD",         "Vulnerable Drivers",     "Loaded drivers matching known bring-your-own-vulnerable-driver names"),
        };
        foreach (var c in behavioural)
            y = AddSettingCheckbox(page, c.Key, c.Label, c.Desc, _config.IsCategoryEnabled(c.Key), y);

        // -------- Display section --------
        y = AddSectionHeader(page, "Display & Behavior", y + 8);
        y = AddSettingCheckbox(page, "EnableToastNotifications", "Enable Toast Notifications",    "Show Windows toast/balloon notifications for alerts", _config.EnableToastNotifications, y);
        y = AddSettingCheckbox(page, "BeepOnAlert",              "Beep on Alert",                 "Play system beep when alerts occur", _config.BeepOnAlert, y);

        // -------- Firewall Profiles --------
        y = AddSectionHeader(page, "Firewall Profiles  [admin]", y + 8);
        y = AddSettingCheckbox(page, "FW_DomainProfile",  "Domain Firewall Profile",  "Enable Windows Firewall for domain networks",        _config.FW_DomainProfile,  y);
        y = AddSettingCheckbox(page, "FW_PrivateProfile", "Private Firewall Profile", "Enable Windows Firewall for private/home networks",  _config.FW_PrivateProfile, y);
        y = AddSettingCheckbox(page, "FW_PublicProfile",  "Public Firewall Profile",  "Enable Windows Firewall for public networks",        _config.FW_PublicProfile,  y);

        // -------- Firewall Block Rules --------
        y = AddSectionHeader(page, "Firewall Block Rules  [admin]", y + 8);
        y = AddSettingCheckbox(page, "FW_BlockInbound",  "Block All Inbound",   "Create a managed rule that blocks all incoming traffic until removed", _config.FW_BlockInbound,  y);
        y = AddSettingCheckbox(page, "FW_BlockPing",     "Block ICMP Ping",     "Block incoming ping requests",                              _config.FW_BlockPing,     y);
        y = AddSettingCheckbox(page, "FW_BlockLAN",      "Block LAN Traffic",   "Block all local network traffic",                           _config.FW_BlockLAN,      y);
        y = AddSettingCheckbox(page, "FW_BlockDevices",  "Block Device Discovery", "Block SMB / NetBIOS / LLMNR / mDNS",                     _config.FW_BlockDevices,  y);

        // -------- Host-Based Protection --------
        y = AddSectionHeader(page, "Host-Based Protection  [admin]", y + 8);
        y = AddSettingCheckbox(page, "PF_BlockTrackers",  "Block Trackers",     "Block known tracking domains via hosts file",          _config.PF_BlockTrackers,  y);
        y = AddSettingCheckbox(page, "PF_BlockMalware",   "Block Malware",      "Block known malware domains via hosts file",            _config.PF_BlockMalware,   y);
        y = AddSettingCheckbox(page, "PF_BlockTelemetry", "Block Telemetry",    "Block Windows and third-party telemetry domains",       _config.PF_BlockTelemetry, y);

        // -------- DNS section --------
        y = AddSectionHeader(page, "DNS & Secure DNS  [admin]", y + 8);
        var dnsLabel = new Label
        {
            Text      = "DNS Provider:",
            Font      = new Font("Segoe UI", 10, FontStyle.Bold),
            ForeColor = Theme.TextMain,
            AutoSize  = true,
            Location  = new Point(20, y + 6),
        };
        page.Controls.Add(dnsLabel);
        var dnsCombo = new ComboBox
        {
            Location      = new Point(160, y + 4),
            Size          = new Size(220, 24),
            DropDownStyle = ComboBoxStyle.DropDownList,
            BackColor     = Theme.Card,
            ForeColor     = Theme.TextMain,
            FlatStyle     = FlatStyle.Flat,
            Font          = Theme.Body(9),
        };
        dnsCombo.Items.AddRange(
            DnsConfiguration.ProviderNames.ToArray<object>());
        dnsCombo.SelectedItem = _config.DNS_Provider;
        dnsCombo.SelectedIndexChanged += OnDnsProviderChanged;
        page.Controls.Add(dnsCombo);
        _dnsProviderCombo = dnsCombo;
        var dnsApply = new Button
        {
            Text      = "Apply / Repair",
            Location  = new Point(392, y + 3),
            Size      = new Size(126, 28),
            FlatStyle = FlatStyle.Flat,
            BackColor = Theme.AccentDim,
            ForeColor = Theme.TextMain,
            Font      = Theme.Body(9, FontStyle.Bold),
            Cursor    = Cursors.Hand,
        };
        dnsApply.FlatAppearance.BorderSize = 0;
        dnsApply.Click += OnApplyDnsClick;
        page.Controls.Add(dnsApply);
        _dnsApplyButton = dnsApply;

        var dnsStatus = new Label
        {
            Text      = "Ready to apply and verify",
            Location  = new Point(160, y + 35),
            AutoSize  = true,
            Font      = Theme.Body(8.5f),
            ForeColor = Theme.TextDim,
        };
        page.Controls.Add(dnsStatus);
        _dnsStatusLabel = dnsStatus;
        y += 58;

#if STORE_BUILD
        var dohNotice = new Label
        {
            Text = "Manage DNS encryption in Windows network settings for the selected adapter.",
            Location = new Point(20, y),
            Size = new Size(800, 34),
            Font = Theme.Body(9),
            ForeColor = Theme.TextDim,
            Anchor = AnchorStyles.Top | AnchorStyles.Left | AnchorStyles.Right,
        };
        page.Controls.Add(dohNotice);
        y += 38;
        var windowsDnsSettings = new Button
        {
            Text = "Open Windows Network Settings",
            Location = new Point(20, y),
            Size = new Size(290, 32),
            FlatStyle = FlatStyle.Flat,
            BackColor = Theme.AccentDim,
            ForeColor = Theme.TextMain,
            Font = Theme.Body(9),
            Cursor = Cursors.Hand,
        };
        windowsDnsSettings.FlatAppearance.BorderSize = 0;
        windowsDnsSettings.Click += (_, _) =>
        {
            try
            {
                System.Diagnostics.Process.Start(new System.Diagnostics.ProcessStartInfo(
                    "ms-settings:network-status") { UseShellExecute = true });
            }
            catch (Exception ex)
            {
                _logger.Error($"Windows network settings: {ex.Message}");
                MessageBox.Show(this, "Open Windows Settings > Network & internet to " +
                    "manage DNS encryption for your adapter.", "Windows Network Settings",
                    MessageBoxButtons.OK, MessageBoxIcon.Information);
            }
        };
        page.Controls.Add(windowsDnsSettings);
        y += 40;
#else
        y = AddSettingCheckbox(page, "DNS_DoH", "Enable DNS over HTTPS", "Encrypt DNS queries (requires compatible provider)", _config.DNS_DoH, y);
#endif
        ApplyDnsControlState();

        // Final padding so the last setting isn't flush with the bottom edge
        page.Controls.Add(new Panel { Location = new Point(0, y + 24), Size = new Size(1, 1) });
        page.Resize += (_, _) =>
        {
            if (page.ClientSize.Width < 360) return;
            foreach (Control control in page.Controls)
            {
                if (control is Panel panel && panel.Width > 700)
                    panel.Width = Math.Max(
                        280, page.ClientSize.Width - panel.Left - 16);
            }
            subtitle.Width = Math.Max(280, page.ClientSize.Width - 20);
            page.AutoScrollMinSize = new Size(0, y + 36);
        };

        return page;
    }

    private int AddSectionHeader(Panel page, string text, int y)
    {
        var sep = new Panel
        {
            Location  = new Point(8, y + 4),
            Size      = new Size(840, 1),
            BackColor = Theme.Separator,
        };
        page.Controls.Add(sep);

        var lbl = new Label
        {
            Text      = text,
            Font      = Theme.SectionTitle(),
            ForeColor = Theme.AccentBlue,
            AutoSize  = true,
            UseMnemonic = false,
            Location  = new Point(8, y + 10),
        };
        page.Controls.Add(lbl);
        return y + 38;
    }

    private int AddSettingCheckbox(Panel page, string key, string label, string desc, bool initial, int y)
    {
        var card = new Panel
        {
            Location  = new Point(20, y),
            Size      = new Size(820, 46),
            BackColor = Theme.Card,
        };
        card.Anchor = AnchorStyles.Top | AnchorStyles.Left | AnchorStyles.Right;

        var cb = new CheckBox
        {
            Text      = label,
            Location  = new Point(14, 6),
            Size      = new Size(420, 20),
            Font      = new Font("Segoe UI", 10, FontStyle.Bold),
            ForeColor = Theme.TextMain,
            BackColor = Theme.Card,
            Tag       = key,
            Checked   = initial,
        };
        cb.CheckedChanged += OnSettingsCheckChanged;
        card.Controls.Add(cb);
        _settingsCheckboxes[key] = cb;

        var d = new Label
        {
            Text      = desc,
            Location  = new Point(34, 26),
            Size      = new Size(770, 16),
            Font      = Theme.Body(8),
            ForeColor = Theme.TextDim,
            BackColor = Theme.Card,
        };
        d.Anchor = AnchorStyles.Top | AnchorStyles.Left | AnchorStyles.Right;
        card.Controls.Add(d);

        page.Controls.Add(card);
        return y + 52;
    }

    // ============================================================================
    //  PAGE 5: LOGS
    // ============================================================================
    private Panel BuildLogsPage()
    {
        var page = new Panel { BackColor = Theme.Bg, AutoScroll = true };
        // Keep all log-page content inside one docked body. Directly placing
        // wide cards on an AutoScroll panel makes WinForms cache their
        // pre-layout width and can leave a phantom horizontal scrollbar.
        var body = new Panel
        {
            BackColor = Theme.Bg,
            Dock = DockStyle.Top,
            Size = new Size(864, 110),
        };
        page.Controls.Add(body);

        var title = new Label
        {
            Text      = "Log Files",
            Font      = Theme.PageTitle(),
            ForeColor = Theme.Accent,
            AutoSize  = true,
            Location  = new Point(8, 8),
        };
        body.Controls.Add(title);

        var subtitle = new Label
        {
            Text      = "Every log file under the data directory. Click any card to open in Notepad. Files older than 30 days are pruned automatically at startup.",
            Font      = Theme.Body(9),
            ForeColor = Theme.TextDim,
            AutoSize  = false,
            Size      = new Size(600, 36),
            Location  = new Point(8, 44),
        };
        body.Controls.Add(subtitle);
        FitToParent(subtitle, rightMargin: 24);

        var logsDir = Paths.LogsDir;
        var files = new List<FileInfo>();
        try
        {
            if (Directory.Exists(logsDir))
            {
                foreach (var f in Directory.EnumerateFiles(logsDir, "*.log"))
                    files.Add(new FileInfo(f));
            }
        }
        catch { /* ignored */ }
        // Newest first so today's logs are at the top
        files.Sort((a, b) => b.LastWriteTime.CompareTo(a.LastWriteTime));

        if (files.Count == 0)
        {
            var empty = new Label
            {
                Text      = "(no log files yet — they appear after the first scan tick)",
                Font      = Theme.Body(9),
                ForeColor = Theme.TextDim,
                AutoSize  = true,
                Location  = new Point(8, 80),
            };
            body.Controls.Add(empty);
            return page;
        }

        int y = 80;
        foreach (var fi in files)
        {
            var card = new Panel
            {
                Location  = new Point(8, y),
                Size      = new Size(840, 56),
                BackColor = Theme.Card,
                Cursor    = Cursors.Hand,
                Tag       = fi.FullName,
                Anchor    = AnchorStyles.Top | AnchorStyles.Left | AnchorStyles.Right,
            };
            card.Click += OnOpenFileClick;

            var t = new Label
            {
                Text      = fi.Name,
                Font      = new Font("Segoe UI", 11, FontStyle.Bold),
                ForeColor = Theme.AccentBlue,
                AutoSize  = true,
                Location  = new Point(16, 8),
            };
            t.Click += OnOpenFileClick;
            t.Tag    = card.Tag;
            card.Controls.Add(t);

            var d = new Label
            {
                Text      = $"{FormatFileSize(fi.Length)}   ·   {fi.LastWriteTime:yyyy-MM-dd HH:mm}",
                Font      = Theme.Mono(9),
                ForeColor = Theme.TextDim,
                AutoSize  = true,
                Location  = new Point(16, 30),
            };
            d.Click += OnOpenFileClick;
            d.Tag    = card.Tag;
            card.Controls.Add(d);

            body.Controls.Add(card);
            y += 64;
        }
        body.Height = y + 12;

        return page;
    }

    private static string FormatFileSize(long bytes)
    {
        if (bytes < 1024)            return $"{bytes} B";
        if (bytes < 1024 * 1024)     return $"{bytes / 1024.0:F1} KB";
        if (bytes < 1024 * 1024 * 1024) return $"{bytes / (1024.0 * 1024):F1} MB";
        return $"{bytes / (1024.0 * 1024 * 1024):F2} GB";
    }

    // ============================================================================
