            Font      = new Font("Segoe UI", 9, FontStyle.Bold),
            Cursor    = Cursors.Hand,
        };
        clearBtn.FlatAppearance.BorderSize = 0;
        clearBtn.Click += OnClearConsoleClick;
        header.Controls.Add(clearBtn);

        var saveBtn = new Button
        {
            Text      = "Save to File",
